sys_script.script:
(function executeRule(current, previous /*null when async*/) {

    try {
        var grRequest = new GlideRecord('x_snc_flowops_guest_request');
        grRequest.initialize();

        // Standard Schema Fields (from database spec)
        grRequest.raw_text = current.short_description;
        grRequest.channel = current.channel || 'walkup_portal';
        grRequest.channel_reference = current.getUniqueValue(); // Interaction sys_id
        grRequest.status = 'New';

        // Custom string fields - set safely if they exist on your request table
        if (grRequest.isValidField('u_guest_name')) {
            grRequest.u_guest_name = current.x_snc_flowops_guest_name;
        } else if (grRequest.isValidField('guest_name')) {
            grRequest.guest_name = current.x_snc_flowops_guest_name;
        }

        if (grRequest.isValidField('u_room_number')) {
            grRequest.u_room_number = current.x_snc_flowops_room_number;
        } else if (grRequest.isValidField('room_number')) {
            grRequest.room_number = current.x_snc_flowops_room_number;
        }

        if (grRequest.isValidField('u_hotel_name')) {
            grRequest.u_hotel_name = current.x_snc_flowops_hotel_name;
        } else if (grRequest.isValidField('hotel_name')) {
            grRequest.hotel_name = current.x_snc_flowops_hotel_name;
        }

        var requestSysId = grRequest.insert();

        if (requestSysId) {
            gs.info('FlowOps Success: Created Guest Request ' + requestSysId + ' from Interaction ' + current.number);
        } else {
            gs.error('FlowOps Failed: GlideRecord insert returned null for x_snc_flowops_guest_request');
        }

    } catch (ex) {
        gs.error('FlowOps Exception in Business Rule: ' + ex.message);
    }

})(current, previous);
